const { accessSync, constants } = await import('node:fs');
const filePath = '/tmp/qrcode.txt';
try {
  accessSync(filePath, constants.R_OK);
} catch (e) {
  throw new Error('File not accessible');
}
globalThis.filePath = filePath;

const { readFileSync } = await import('node:fs');
const data = readFileSync(globalThis.filePath, { encoding: 'utf8' });
globalThis.qrContent = data.trim();

if (!globalThis.qrContent) {
  throw new Error('Empty QR content');
}
globalThis.finalResult = globalThis.qrContent;
